// Entry point of the Cloudflare Workers build (wrangler.jsonc): the OpenNext
// worker plus the two daily jobs that vercel.json ran through Vercel Cron.
// Not part of the Next.js app - excluded from tsconfig.json; wrangler bundles it.
// Generated by `npm run cf:build`.
import handler, { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "../.open-next/worker.js";

const CRON_ROUTES: Record<string, string> = {
  "17 3 * * *": "/api/cron/webhooks",
  "32 3 * * *": "/api/cron/admin-usage",
};

interface Env {
  CRON_SECRET?: string;
  APP_URL?: string;
}

const worker = {
  fetch: handler.fetch,
  // The routes check `Authorization: Bearer $CRON_SECRET` themselves and
  // answer 503 until it is set (src/app/api/cron/*/route.ts).
  async scheduled(event: { cron: string }, env: Env, ctx: unknown) {
    const path = CRON_ROUTES[event.cron];
    if (!path) return;
    const request = new Request(new URL(path, env.APP_URL ?? "https://useguidon.com"), {
      headers: { Authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    const response = await handler.fetch(request, env, ctx);
    if (!response.ok) console.error(`cron ${path} answered ${response.status}`);
  },
};

export default worker;
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge };
